WITH base AS (SELECT * FROM order_items WHERE quantity != 5 OR order_id IN (15, 22, 23, 25)), quantity_bucket_summary AS (SELECT CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(*) AS num_order_items FROM base GROUP BY CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END) SELECT * FROM quantity_bucket_summary ORDER BY quantity_bucket ASC;
